/* Segment, field, datatype, message-structure and code-table definitions for HL7 v2.1 to v2.9.
 * The JSON is generated by tools/build_schema.py from the HL7 v2.xml schemas. */

export interface FieldDef {
  number: number;
  name: string;
  dataType: string;
  tableId?: string;
  required: boolean;
  repeating: boolean;
  withdrawn: boolean;
}

export interface ComponentDef {
  number: number;
  name: string;
  dataType: string;
  tableId?: string;
}

export interface StructureItem {
  segment?: string;
  group?: string;
  min: number;
  max: number; // -1 = unbounded
  items: StructureItem[];
}

export interface TableDef {
  id: string;
  name: string;
  values: Record<string, string>;
}

interface RawPart { n: string; t: string; tb?: string; r?: number; rp?: number; w?: number }
interface RawItem { s?: string; g?: string; min: number; max: number; items?: RawItem[] }
interface RawVersion {
  segments: Record<string, RawPart[]>;
  datatypes: Record<string, RawPart[]>;
  structures: Record<string, RawItem[]>;
}

// Static requires so Metro bundles every version; each is parsed only when first used.
const LOADERS: Record<string, () => RawVersion> = {
  '2.1': () => require('./schema/v2.1.json'),
  '2.2': () => require('./schema/v2.2.json'),
  '2.3': () => require('./schema/v2.3.json'),
  '2.3.1': () => require('./schema/v2.3.1.json'),
  '2.4': () => require('./schema/v2.4.json'),
  '2.5': () => require('./schema/v2.5.json'),
  '2.5.1': () => require('./schema/v2.5.1.json'),
  '2.7.1': () => require('./schema/v2.7.1.json'),
  '2.8': () => require('./schema/v2.8.json'),
  '2.8.2': () => require('./schema/v2.8.2.json'),
  '2.9': () => require('./schema/v2.9.json'),
};

export const VERSIONS = Object.keys(LOADERS);
export const DEFAULT_VERSION = '2.5.1';

let tablesCache: Record<string, TableDef> | null = null;
export function tables(): Record<string, TableDef> {
  if (!tablesCache) {
    const raw: Record<string, { n?: string; v?: Record<string, string> }> = require('./schema/tables.json');
    tablesCache = {};
    for (const [id, t] of Object.entries(raw)) tablesCache[id] = { id, name: t.n ?? '', values: t.v ?? {} };
  }
  return tablesCache;
}

export function table(id?: string | null): TableDef | undefined {
  if (!id) return undefined;
  return tables()[id.replace(/^HL7/i, '')];
}

export function lookupTable(tableId: string | undefined | null, value: string | undefined | null): string | undefined {
  if (!value) return undefined;
  const d = table(tableId)?.values[value];
  return d ? d : undefined;
}

const capitalise = (s: string) => (s ? s[0].toUpperCase() + s.slice(1) : s);
const normaliseType = (t?: string) => (!t ? '' : t === '*' || t === 'var' || t === 'varies' ? 'varies' : t);

function parseVersion(v: string): number[] | null {
  const parts = v.split('.').map(Number);
  return parts.length >= 2 && parts.every((n) => Number.isInteger(n)) ? parts : null;
}

function compareVersions(a: number[], b: number[]): number {
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const x = a[i] ?? 0;
    const y = b[i] ?? 0;
    if (x !== y) return x - y;
  }
  return 0;
}

/** The closest bundled version for an MSH-12 value (2.6 falls back to 2.5.1, 2.7 to 2.7.1). */
export function resolveVersion(version?: string | null): string {
  const v = (version ?? '').trim();
  if (LOADERS[v]) return v;
  const wanted = parseVersion(v);
  if (!wanted) return DEFAULT_VERSION;
  const family = VERSIONS.filter((x) => x.startsWith(v + '.')).pop();
  if (family) return family;
  return VERSIONS.filter((x) => compareVersions(parseVersion(x)!, wanted) <= 0).pop() ?? VERSIONS[0];
}

const STRUCTURE_ALIASES: Record<string, string> = {
  ADT_A04: 'ADT_A01', ADT_A08: 'ADT_A01', ADT_A13: 'ADT_A01', ADT_A14: 'ADT_A05', ADT_A28: 'ADT_A05',
  ADT_A31: 'ADT_A05', ADT_A07: 'ADT_A06', ADT_A10: 'ADT_A09', ADT_A11: 'ADT_A09', ADT_A40: 'ADT_A39',
  ADT_A41: 'ADT_A39', ADT_A42: 'ADT_A39', ORU_W01: 'ORU_R01', SIU_S13: 'SIU_S12', SIU_S14: 'SIU_S12',
  SIU_S15: 'SIU_S12', SIU_S17: 'SIU_S12', SIU_S26: 'SIU_S12', MDM_T03: 'MDM_T01', MDM_T05: 'MDM_T01',
  MDM_T07: 'MDM_T01', MDM_T09: 'MDM_T01', MDM_T11: 'MDM_T01', MDM_T04: 'MDM_T02', MDM_T06: 'MDM_T02',
  MDM_T08: 'MDM_T02', MDM_T10: 'MDM_T02',
};

export class Schema {
  readonly version: string;
  private readonly segments: Record<string, FieldDef[]> = {};
  private readonly datatypes: Record<string, ComponentDef[]> = {};
  private readonly structures: Record<string, StructureItem[]> = {};

  private constructor(version: string, raw: RawVersion) {
    this.version = version;
    for (const [id, fields] of Object.entries(raw.segments)) {
      this.segments[id] = fields.map((f, i) => ({
        number: i + 1, name: capitalise(f.n), dataType: normaliseType(f.t), tableId: f.tb,
        required: f.r === 1, repeating: f.rp === 1, withdrawn: f.w === 1,
      }));
    }
    for (const [id, comps] of Object.entries(raw.datatypes)) {
      if (comps.length) this.datatypes[id] = comps.map((c, i) => ({ number: i + 1, name: capitalise(c.n), dataType: normaliseType(c.t), tableId: c.tb }));
    }
    const toItem = (r: RawItem): StructureItem => ({ segment: r.s, group: r.g, min: r.min, max: r.max, items: (r.items ?? []).map(toItem) });
    for (const [id, items] of Object.entries(raw.structures)) this.structures[id] = items.map(toItem);
  }

  private static cache = new Map<string, Schema>();

  static for(version?: string | null): Schema {
    const v = resolveVersion(version);
    let s = Schema.cache.get(v);
    if (!s) {
      s = new Schema(v, LOADERS[v]());
      Schema.cache.set(v, s);
    }
    return s;
  }

  hasSegment(id: string): boolean {
    return id in this.segments;
  }

  segment(id: string): FieldDef[] | undefined {
    return this.segments[id];
  }

  field(segment: string, n: number): FieldDef | undefined {
    return this.segments[segment]?.[n - 1];
  }

  /** Components of a composite datatype; undefined for primitives such as ST or NM. */
  dataType(id?: string): ComponentDef[] | undefined {
    if (!id) return undefined;
    if (this.datatypes[id]) return this.datatypes[id];
    // Borrow from other versions (TS became DTM, CE became CWE ...).
    for (const v of [...VERSIONS].reverse()) {
      if (v === this.version) continue;
      const d = Schema.for(v).datatypes[id];
      if (d) return d;
    }
    return undefined;
  }

  structure(id?: string | null): StructureItem[] | undefined {
    return id ? this.structures[id] : undefined;
  }

  /** Works out the message structure from MSH-9 (e.g. ADT^A04 uses ADT_A01). */
  resolveStructure(code: string, trigger: string, declared: string): string | undefined {
    if (declared && this.structures[declared]) return declared;
    const direct = `${code}_${trigger}`;
    if (this.structures[direct]) return direct;
    // Table 0354 lists the events that share each structure ("A01 A04 A08 A13").
    for (const [structure, events] of Object.entries(table('0354')?.values ?? {})) {
      if (structure.startsWith(code + '_') && events.split(/[ ,;]+/).includes(trigger) && this.structures[structure]) return structure;
    }
    const alias = STRUCTURE_ALIASES[direct];
    if (alias && this.structures[alias]) return alias;
    if (this.structures[code]) return code;
    return undefined;
  }
}
